entries[272109] = { ["name"] = "Auslöschungsstrahl", ["text"] = "Sofort\nBeschwört eine Vergessenssphäre in der Nähe eines Gegners. Die Vergessenssphäre betört alle Spielercharaktere innerhalb von 5 Metern.\n\nWährend der Betörung erhalten die Betroffenen alle 2 Sek. jeweils Stapel von 'Vernichtung'.\n\nSpielercharaktere bleiben unter der Kontrolle der Sphäre, bis sie aus dem Wirkungsbereich gestoßen werden. Angriffe auf Spielercharaktere unter dem Einfluss der Vergessenssphäre stoßen diese ein Stück zurück.\n\nWenn ein Spielercharakter vom Einfluss befreit wird, löst er 'Hereinbrechendes Vergessen' aus." }
entries[272110] = { ["name"] = "Auslöschungsstrahl", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine Vergessenssphäre in der Nähe eines Gegners. Die Vergessenssphäre betört alle Spielercharaktere innerhalb von 5 Metern.\n\nWährend der Betörung erhalten die Betroffenen alle 2 Sek. jeweils Stapel von 'Vernichtung'.\n\nSpielercharaktere bleiben unter der Kontrolle der Sphäre, bis sie aus dem Wirkungsbereich gestoßen werden. Angriffe auf Spielercharaktere unter dem Einfluss der Vergessenssphäre stoßen diese ein Stück zurück.\n\nWenn ein Spielercharakter vom Einfluss befreit wird, löst er 'Hereinbrechendes Vergessen' aus." }
