entries[272118] = { ["name"] = "Gunst von Gonk", ["text"] = "Sofort\nWenn Ihr mindestens 2 Gegner innerhalb von 10 Metern versammelt, ruft Ihr ein Kriegsrudel herbei.\n\nDieser Effekt kann nur ein Mal alle 3 Min. auftreten.\n\nKriegsrudel\nKinder von Gonk kommen Euch zu Hilfe.\n(3Min. Abklingzeit)" }
entries[272119] = { ["name"] = "Gunst von Pa'ku", ["text"] = "Sofort\nDas Töten eines Ziels löst Winde von Pa'ku aus.\n\nDieser Effekt kann nur einmal alle 60 Sek. auftreten.\n\nWinde von Pa'ku\nErhöht 15 Sek. lang das Tempo um 5% und die Bewegungsgeschwindigkeit um 25%.\n(1Min. Abklingzeit)" }
