entries[272121] = { ["name"] = "Gunst von Akunda", ["text"] = "Sofort\nAngriffe und Heilungen haben eine Chance, Lichtsturm auszulösen.\n\nDieser Effekt kann nur einmal alle 60 Sek. auftreten.\n\nLichtsturm\nVerbreitet Lichtsturmenergie auf das Ziel, die auf Ziele in der Nähe überspringt und dabei Verbündete heilt oder Gegnern Schaden zufügt.\n(1Min. Abklingzeit)" }
entries[272122] = { ["name"] = "Gunst von Bwonsamdi", ["text"] = "Sofort\nBeim Töten eines Gegners besteht eine Chance, dass Pakt mit Bwonsamdi ausgelöst wird.\n\nPakt mit Bwonsamdi\nEin Fluch, der nach 4 Sek. explodiert und allen Gegnern in der Nähe Schaden zufügt sowie einen Diener von Bwonsamdi beschwört.\n(Procchance: 50%, 3s Abklingzeit)" }
entries[272123] = { ["name"] = "Gunst von Kimbul", ["text"] = "Sofort\nChance, bei Angriffen Kimbuls Verwundung hervorzurufen.\n\nDieser Effekt kann nur einmal alle 60 Sek. auftreten.\n\nKimbuls Verwundung\nVerursacht alle 1 Sek. 10 körperlichen Schaden.\n(1Min. Abklingzeit)" }
