entries[272275] = { ["name"] = "Kräftigende Kühle", ["text"] = "Azeritmacht\nSofort\nCa. 1 Procs pro Minute\nEure Heilungen haben eine Chance, 'Kräftigende Kühle' hervorzurufen. Ein Ziel zu heilen, das mit 'Kräftigende Kühle' belegt ist, ruft zusätzlich 376 Heilung hervor und lässt 'Kräftigende Kühle' auf einen Verbündeten in der Nähe überspringen. Bis zu 6 Sprünge insgesamt." }
